C(10, 1, "Familia ocupada, familia conectada", [
 ("gancho", "marisol", "[curioso, intriga, ritmo ágil] Mucha actividad en la familia. ¿Pero hay conexión?"),
 ("idea", "marisol", "[cálido, cercano, ritmo ágil] En Padres confiados, Jim Burns habla de ser una generación de transición: la que decide vencer los patrones familiares negativos. Es decir, no repetir sin pensar lo que tú viviste. Eso requiere decidirlo a propósito."),
 ("cita", "marisol", "[firme, cálido, pausado] Así describe una persona a la familia en la que creció: «involucrados en muchas cosas, pero no conectados»."),
 ("giro", "marisol", "[cálido, cercano, ritmo ágil] Desde afuera parecían estar bien, ocupados con el trabajo, la iglesia y la escuela. Pero por dentro les faltaba conexión. Todo en orden. Todo en marcha."),
 ("papa", "mario", "[papá, cansado, a la defensiva] Es que no paramos: trabajo, escuela, iglesia..."),
 ("joven", "rewe", "[adolescente, casual, bajito] Estamos juntos, pero cada quien en lo suyo."),
 ("accion", "marisol", "[firme, cálido, cierre] Para hoy: mira tu semana y busca un hueco que sea solo de tu familia. No para hacer cosas buenas. Solo para estar juntos. Una cena. Una caminata. Un helado. Lo que sea, pero juntos."),
 ("siguiente", "marisol", "[sereno, cierre] Siguiente: un día de descanso para toda la familia."),
], [
 ("titular", "gancho", "conexión", "¿Actividad o conexión?", "Dos palabras: «actividad» llena de engranes, «conexión» con un hilo"),
 ("icono", "idea", "transición", "Generación de transición", "Puente pequeño que une dos orillas"),
 ("cita", "cita", "involucrados", "«Involucrados en muchas cosas, pero no conectados»", "Tarjeta de cita: Jim Burns, Padres confiados (relato de una persona sobre su familia)"),
 ("ilustracion", "giro", "afuera", "Todo parecía estar bien", "Casa iluminada por fuera; por dentro, cuartos separados con luces apagadas"),
 ("reaccion", "papa", "paramos", "Es que no paramos", "Burbuja de papá con calendario lleno"),
 ("reaccion", "joven", "cada", "Juntos, pero cada quien en lo suyo", "Burbuja del adolescente"),
 ("accion", "accion", "hueco", "Para hoy: un hueco solo de tu familia", "Tarjeta «Para hoy»; un espacio vacío en el calendario brilla"),
 ("icono", "accion", "juntos", "Solo para estar juntos", "Mesa con cuatro sillas, sin personas, una luz cálida"),
 ("titular", "siguiente", "descanso", "Siguiente: un día de descanso", "Hamaca que se mece"),
], [GB + ", Burns: «involucrados en muchas cosas, pero no conectados» (PT57); generación de transición"])

C(10, 2, "El día de descanso en familia", [
 ("gancho", "marisol", "[curioso, intriga, ritmo ágil] ¿Cuándo fue la última vez que tu familia descansó de verdad, en familia?"),
 ("idea", "marisol", "[cálido, cercano, ritmo ágil] Burns dedica una de sus lecciones al día de reposo. Dice que muchas familias tienen una gran necesidad de descanso. Quizá la tuya también."),
 ("cita", "marisol", "[firme, cálido, pausado] Lo resume así: «Están tan ocupadas haciendo cosas buenas que han perdido el camino para llegar a las cosas mejores»."),
 ("giro", "marisol", "[cálido, cercano, ritmo ágil] Y propone cuatro verbos: reposar, refrescar, restaurar y recrearse. Sobre reposar, sugiere hacer algo que genere un descanso de verdad. Y si no sabes qué es, preguntarles a ellos. Cuatro verbos, para un solo día."),
 ("papa", "mario", "[papá, cansado, a la defensiva] ¿Descansar? Los domingos tengo pendientes."),
 ("joven", "rewe", "[adolescente, casual, directo] Yo descanso cuando nadie me está pidiendo nada. O sea, casi nunca."),
 ("accion", "marisol", "[firme, cálido, cierre] Para hoy: pregunta en la mesa qué les daría descanso de verdad como familia, y apunta lo que respondan. Sin juzgar las respuestas. Y si se puede, hazlo esta semana."),
 ("siguiente", "marisol", "[sereno, cierre] Siguiente: una bendición no tiene que ser elocuente."),
], [
 ("titular", "gancho", "descansó", "¿Cuándo descansó tu familia de verdad?", "Sillones vacíos frente a una ventana con luz de tarde"),
 ("icono", "idea", "reposo", "Día de reposo familiar", "Calendario con un día en amarillo"),
 ("cita", "cita", "ocupadas", "«Están tan ocupadas haciendo cosas buenas que han perdido el camino para llegar a las cosas mejores»", "Tarjeta de cita: Jim Burns, Padres confiados"),
 ("reaccion", "papa", "domingos", "¿Descansar? Los domingos tengo pendientes.", "Burbuja de papá"),
 ("icono", "giro", "reposar", "Reposar", "Icono de cama o hamaca"),
 ("icono", "giro", "refrescar", "Refrescar", "Icono de vaso con agua"),
 ("icono", "giro", "restaurar", "Restaurar", "Icono de herramienta que repara una taza"),
 ("icono", "giro", "recrearse", "Recrearse", "Icono de pelota o juego de mesa"),
 ("reaccion", "joven", "nadie", "Yo descanso cuando nadie me pide nada", "Burbuja del adolescente"),
 ("accion", "accion", "mesa", "Para hoy: pregunta qué les daría descanso de verdad", "Tarjeta «Para hoy» con mesa y libreta"),
 ("titular", "siguiente", "elocuente", "Siguiente: la bendición no tiene que ser elocuente", "Palabra «bendición» que se ilumina suave"),
], [GB + ", Burns: cuatro R del día de reposo (PT72); «Están tan ocupadas haciendo cosas buenas…»"])

C(10, 3, "Una bendición sencilla", [
 ("gancho", "marisol", "[curioso, intriga, ritmo ágil] ¿Cuándo fue la última vez que bendijiste a tu hijo con palabras?"),
 ("idea", "marisol", "[cálido, cercano, ritmo ágil] Jim Burns propone cambiar el ambiente del hogar con tres cosas: afecto, calidez y estímulo. Tres palabras fáciles de recordar. Y dedica otra lección a la bendición."),
 ("cita", "marisol", "[firme, cálido, pausado] Escribe: «No tienes que ser elocuente o tener tu vida bajo control para decir palabras de bendición». Para él, el amor es el único requisito. Es decir, no esperes el discurso perfecto."),
 ("giro", "marisol", "[cálido, cercano, ritmo ágil] Y agrega que, aunque las palabras no salgan de la manera correcta, tus hijos pueden entender el mensaje de tus emociones."),
 ("papa", "mario", "[papá, emocionado, sencillo] Hijo, me da orgullo que seas tú. Que Dios te cuide."),
 ("joven", "rewe", "[adolescente, bajito, tímido] Aunque se le trabe, me gusta que me lo diga."),
 ("accion", "marisol", "[firme, cálido, cierre] Para hoy: antes de dormir, dile a tu hijo una frase de bendición. Sencilla, sin discurso, aunque no te salga perfecta."),
 ("tarjeta", "marisol", TARJ + "Padres confiados, de Jim Burns, de Editorial Vida. Este video no sustituye la lectura del libro."),
], [
 ("titular", "gancho", "bendijiste", "¿Cuándo fue la última vez que lo bendijiste?", "Mano abierta con luz amarilla que baja"),
 ("icono", "idea", "afecto", "Afecto", "Corazón"),
 ("icono", "idea", "calidez", "Calidez", "Sol pequeño"),
 ("icono", "idea", "estímulo", "Estímulo", "Flecha hacia arriba"),
 ("cita", "cita", "elocuente", "«No tienes que ser elocuente o tener tu vida bajo control para decir palabras de bendición»", "Tarjeta de cita: Jim Burns, Padres confiados"),
 ("titular", "cita", "requisito", "El amor es el único requisito", "«amor» en morado con subrayado amarillo"),
 ("icono", "giro", "emociones", "Entienden el mensaje de tus emociones", "Onda de voz que se transforma en corazón"),
 ("reaccion", "papa", "orgullo", "Hijo, me da orgullo que seas tú.", "Burbuja de papá, tono cálido"),
 ("reaccion", "joven", "trabe", "Aunque se le trabe, me gusta que me lo diga", "Burbuja del adolescente, tono tímido"),
 ("accion", "accion", "dormir", "Para hoy: una frase de bendición antes de dormir", "Tarjeta «Para hoy» con luna y estrellas"),
 ("tarjeta_libro", "tarjeta", "Vida", "Padres confiados · Jim Burns · Editorial Vida", "Tarjeta de cierre estándar de la serie: portada tipográfica, sin foto; leyenda «Este video no sustituye la lectura del libro»"),
], [GB + ", Burns: «No tienes que ser elocuente…» (PT124); ACE: afecto, calidez y estímulo (PT78)"])
